import { useCallback, lazy, Suspense, useState, useEffect, useRef } from 'react'
import WelcomeHeader from '../components/WelcomeHeader'
import PartnerBenefits from '../components/PartnersBenefits'
import PasarPolisFooter from '../components/PasarPolisFooter'
import { gTagOnSignupNow, gTagOnSignIn } from '../tagManager'
import LazyLoad from 'react-lazyload'
import CircularLoader from '../../../../components/CircularLoader'
import SectionOne from '../components/SectionOne'
import { WelcomeHomeStyle } from './index.style'

import WelcomeBottom from '../components/WelcomeBottom'
import StepsOfGain from '../components/StepsOfGain'

const FAQs = lazy(() => import('../components/FAQs'))
const PasarPolisPartner = lazy(() => import('../components/PasarPolisPartner'))

function WelcomeHome (props) {
  const [stickyBottom, setStickyBottom] = useState(false)
  const that = useRef({ isObeserverSet: false })

  useEffect(() => {
    const observer = new IntersectionObserver((entries, observer) => {
      entries.forEach(entry => {
        if ((entry.boundingClientRect.top) < 145) {
          setStickyBottom(true)
        } else {
          setStickyBottom(false)
        }
      })
    }, { rootMargin: '0px 0px 0px 0px', threshold: [0, 1] })
    const target = document.querySelector('#steps-of-gain')
    observer.observe(target)
    that.current.isObeserverSet = true
    return () => {
      observer.unobserve(target)
    }
  }, [setStickyBottom])

  const handleToLogin = useCallback((path) => {
    if (path === '/registration') {
      // fire ga tag on signup now
      gTagOnSignupNow()
    } else {
      // fire ga tag on signin click
      gTagOnSignIn()
    }
    props.history.push(path)
  }, [props.history])

  return (
    <WelcomeHomeStyle>
      <WelcomeHeader onLogin={handleToLogin} />
      <SectionOne onSignup={handleToLogin} />
      <PartnerBenefits />
      <StepsOfGain />
      <LazyLoad offset={200}>
        <Suspense fallback={<CircularLoader isLoading />}>
          <PasarPolisPartner />
        </Suspense>
      </LazyLoad>
      <LazyLoad offset={200}>
        <Suspense fallback={<CircularLoader isLoading />}>
          <FAQs />
        </Suspense>
      </LazyLoad>
      <WelcomeBottom position={(stickyBottom ? 'sticky' : 'static')} onJoinClick={handleToLogin} />
      <LazyLoad offset={200}>
        <PasarPolisFooter history={props.history} />
      </LazyLoad>
    </WelcomeHomeStyle>
  )
}

export default WelcomeHome
