import { WelcomeFooterStyle } from './index.style'
import { Row } from '../../../../../commonStyle/index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import { LANG_STRINGS } from '../../../../../lang'
import { useCallback } from 'react'
import { OJK } from '../../../../../images'

function PasarPolisFooter (props) {
  const { history } = props

  const handleRedir = useCallback((redir) => {
    history.push(redir)
  }, [history])

  const getLinkButton = useCallback((text, redir) => {
    return (
      <CustomText
        size='10px'
        color={AgentColorPallette.uiGold}
        weight={600}
        onClick={() => handleRedir(redir)}
      >
        {text}
      </CustomText>
    )
  }, [handleRedir])

  return (
    <WelcomeFooterStyle id='footer'>
      <Row justify='space-between' align='center'>
        <div>
          <CustomText
            size='10px'
            color={AgentColorPallette.regular}
          >
            {LANG_STRINGS.mitraIsPartOfPasarpolis}.
          </CustomText>
          <Row justify='space-between' align='center'>
            {getLinkButton(LANG_STRINGS.privacyPolicy, '/privacy-policy')}
            <CustomText
              size='10px'
              color={AgentColorPallette.black}
            >
              &bull;
            </CustomText>
            {getLinkButton(LANG_STRINGS.termsOfUse, '/terms-of-use')}
          </Row>
          <CustomText
            size='10px'
            color={AgentColorPallette.regular}
          >
            ©2021 PasarPolis
          </CustomText>
        </div>
        <img src={OJK} alt='' />
      </Row>
    </WelcomeFooterStyle>
  )
}

export default PasarPolisFooter
